const fs=require('fs'),p=require('path'),crypto=require('crypto');const root=p.resolve(__dirname,'..'),out=p.join(root,'protocol-comunicare'),src=p.join(root,'reconstituit/jadx/app/src/main/java');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const ob='com/alipay/verifyiotidentity/obfuscated/',wifi='com/example/recorde_translate_plugin/glass/wifip2p/',bean='com/iflytek/fanyi/blc/service/bean/';
const ref=(f,l)=>'<a href="../reconstituit/jadx/app/src/main/java/'+f+'">'+esc(l||f)+'</a>';const table=(h,r)=>'<div class="scroll"><table><thead><tr>'+h.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+r.map(x=>'<tr>'+x.map(y=>'<td>'+esc(y)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';const code=x=>'<pre><code>'+esc(x)+'</code></pre>';
function crc(b){let c=0;for(const v of b){c^=v;for(let i=0;i<8;i++)c=((c&128)?(c<<1)^7:c<<1)&255;}return c;}
function frame(obj,seq){const payload=Buffer.from(JSON.stringify(obj)),b=Buffer.alloc(payload.length+17);Buffer.from('aaff5500','hex').copy(b);b[8]=1;b[9]=1;b.writeUInt16LE(seq,10);b.writeUInt16LE(payload.length+3,12);b[14]=1;b[15]=1;payload.copy(b,16);b[b.length-1]=crc(b.subarray(0,-1));return b;}
const example={opt:62003,optNum:1,biz_num:0},packet=frame(example,0);if(packet.toString('hex')!=='aaff55000000000001010000270001017b226f7074223a36323030332c226f70744e756d223a312c2262697a5f6e756d223a307da4'||crc(packet)!==0)throw Error('CRC fixture differs from SDK');
const examples={notice:'Exemple sintetice, neverificate pe hardware; substituenții nu sunt credențiale. biz_num=0 și secvențele sunt alese pentru demonstrație.',battery:{json:example,sequence:0,hex:packet.toString('hex'),bytes:packet.length},wifiStart:{opt:70401,optNum:2,biz_num:0,ctrl:1,ssid:'<SSID>',wifiType:0,pwd:'<PAROLA_WIFI>',wifiBand:'5',wifiChannel:0,encryption:'wpa2'},wifiDownload:{opt:70402,optNum:3,ctrl:1,model:2,upOrDown:2,fileName:'<CALE_FISIER_DE_PE_OCHELARI>',offset:0,fileNoCrc:1,uploadBreakPoint:0},cloudAudio:{type:'data',s:'<SESSION_ID>',l:false,c:{base:{appid:'<APP_ID>',accesskey:'<ACCESS_KEY>',uid:'<USER_ID>',deviceid:'<DEVICE_ID>'},param:{token:'<TOKEN>',source:['<LIMBA_SURSA>'],target:'<LIMBA_TINTA>',reqcodec:{format:'raw',rate:16000,bit:16,channels:1,framesize:640}}}}};
fs.writeFileSync(p.join(out,'exemple.json'),JSON.stringify(examples,null,2));fs.writeFileSync(p.join(out,'exemplu-baterie.bin'),packet);
let b=`<h1>Protocolul de comunicare iFLYTEK — reconstrucție din APK</h1><p>APK <b>com.iflytek.translateapp 1.0.3899</b> · analiză statică, 30 octombrie 2026.</p><nav><a href="../INDEX.html">Catalog APK</a><a href="CATALOG.html">112 constructori și 43 scheme</a><a href="exemple.json">Exemple JSON</a><a href="validation.json">Verificări</a></nav><p class="note">Specificație reconstruită a traseelor observabile, nu documentație oficială sau contract complet al firmware-ului. Sunt separate profilele ochelari/căști și codul comun. Nicio comandă din exemple nu a fost trimisă unui dispozitiv; cloudul și autentificarea nu au fost testate live.</p><nav>${[['straturi','Straturi'],['ble','BLE și conectare'],['cadru','Cadru binar'],['comenzi','Comenzi'],['audio','Audio'],['wifi','Wi-Fi și fișiere'],['cloud','gRPC și API'],['chei','Chei/autentificare'],['flutter','Flutter'],['limite','Ce rămâne de validat']].map(([id,t])=>'<a href="#'+id+'">'+t+'</a>').join('')}</nav>`;
b+=`<h2 id="straturi">1. Straturile comunicației</h2><p>Flutter comunică în interiorul aplicației cu pluginurile Android prin MethodChannel/EventChannel. Pluginurile folosesc GATT pentru controlul ochelarilor și unele fluxuri audio; Wi-Fi Direct și TCP pentru fișiere/OTA; gRPC peste TLS pentru serviciile cloud. Codecurile, cadrele BLE și mesajele gRPC sunt niveluri diferite.</p>`+code('UI Flutter/Dart\n  └─ MethodChannel / EventChannel\n      ├─ BLE GATT → comenzi JSON în cadre binare / audio / notificări\n      ├─ Wi-Fi Direct → TCP → cadre binare / fișiere / OTA\n      └─ TLS + HTTP/2 + gRPC → JSON sau JSON + audio binar\n          └─ STT / traducere / TTS / alte funcții AI');
b+=`<h2 id="ble">2. GATT și conectare</h2>`+table(['Rol','Valoare observată în profilul GLASSES'],[['Serviciu','434f544f-5250-5050-414b-4554594c4669'],['Comenzi scrise','00006001-0000-1000-8000-00805f9b34fb'],['Notificări primite','00006002-0000-1000-8000-00805f9b34fb'],['Caracteristică audio declarată în configurație','6002; traseul concret zb0.L1 trimite audio pe caracteristica de comandă 6001'],['Versiune la emitere','1'],['MTU solicitat de configurație','480; valoarea negociată trebuie citită de la Android/dispozitiv']])+`<p>Surse: ${ref(ob+'l04.java','l04: profil GLASSES')}, ${ref(ob+'zb0.java','zb0: constructor și transmitere')}, ${ref(ob+'wf0.java','wf0: mașina de stări')}.</p><p>Secvența observată include conectarea GATT, descoperirea serviciilor, înregistrarea notificărilor, solicitarea MTU și trecerea în starea conectat. Există un temporizator de conectare de 30 s și programarea înregistrării notificărilor după aproximativ 1 s. Codul poate avansa starea după solicitarea MTU, deci nu trebuie presupus că 480 a fost deja negociat.</p><p>Coada ff0 serializează comenzile, cu timeout implicit 1.000 ms și 3 reîncercări configurabile; include heartbeat la 60 s și mod exclusiv OTA. Familia de ochelari folosește și 62005 ca HELLO. În constructor, biz_num pornește la -1; unele căi îl incrementează, iar coada îl poate seta din ID-ul sarcinii modulo 10.000.000. Nu este o cheie criptografică. ${ref(ob+'ff0.java','Coada, corelarea și heartbeat')}</p><p>Nu am verificat negocierea bonding/criptarea radio și nici secvența completă de activare pentru un anumit firmware. CRC-ul și JSON-ul de mai jos nu descriu securitatea stratului Bluetooth.</p>`;
b+=`<h2 id="cadru">3. Cadrul binar comun</h2><p>Antetul are 14 octeți. Câmpul length include payload-ul și octetul final CRC; lungimea totală este 14 + length.</p>`+table(['Offset','Lungime','Câmp și reprezentare'],[['0','4','Magic: AA FF 55 00'],['4','4','handle: 00 00 00 00 în constructorii observați'],['8','1','version'],['9','1','opCode: 1 request, 2 response, 3 indication, 4 notification'],['10','2','sequenceId, little-endian; contorul de cadru pornește de la 0'],['12','2','length, little-endian; payload + CRC'],['14','variabil','payload; începe cu moduleID și msgID'],['ultimul','1','CRC-8: polinom 0x07, init 0, fără reflexie, xor final 0']])+`<p>Terminologia din raportul inițial este corectată: offsetul 9 este opCode, nu canal audio; offsetul 14 este moduleID, iar offsetul 15 este msgID. Pentru JSON, moduleID=1 și msgID=1 în builderul analizat. CRC se calculează pe toți octeții anteriori lui. Echivalent, implementarea Wi-Fi verifică CRC pe întreg cadrul și așteaptă rezultatul zero.</p><p>${ref(wifi+'wifi/protocol/ProtocolHeader.java','ProtocolHeader')} · ${ref(wifi+'wifi/protocol/IBluetoothProtocol.java','Constante cadru')} · ${ref(wifi+'wifi/protocol/ProtocolUtil.java','CRC')} · ${ref(ob+'gf0.java','Reasamblare BLE')}.</p><p>O notificare BLE nu trebuie confundată cu un cadru complet. gf0 acumulează fragmente, folosește magic pentru început și compară lungimea acumulată cu antetul. Dispatcherul său transmite opCode=2 către răspunsuri și opCode=4 către notificări. Parserul observat nu este un parser generic robust pentru orice concatenare de cadre; un SDK nou trebuie să trateze explicit cadrele fragmentate, concatenate și lungimile invalide.</p><h3>Exemplu reproductibil: cerere de baterie</h3><p>Valorile de secvență și biz_num sunt alese pentru test, nu constituie handshake.</p>`+code(JSON.stringify(example))+code(packet.toString('hex').match(/.{1,2}/g).join(' '))+`<p>JSON: 36 octeți; length=39 (0x0027); cadru=53 octeți; CRC=0xA4. Ordinea proprietăților și spațiile pot schimba octeții și CRC, fără să schimbe sensul JSON. <a href="exemplu-baterie.bin">Cadru binar</a>.</p>`;
b+=`<h2 id="comenzi">4. Comenzi JSON și răspunsuri</h2><p>Schema comună BLE: opt (operație), optNum (identificator comandă), biz_num (identificator logic) și parametrii funcției. sequenceId din antet este un contor separat. optNum începe la 1 și revine la 1 după 65535; sequenceId revine la 0. În răspunsuri, errCode=0 este tratat ca succes în numeroase handlere. Rezultatul complet depinde de opt; nu există o schemă universală de răspuns pentru toate dispozitivele.</p>`+table(['opt','Funcție observată / câmpuri'],[['62001','Informații sistem, pentru handlerul CoreBluetoothDevice'],['62002','Versiune în handlerul ochelarilor; există și builder comun de redenumire cu oldName/newName'],['62003','Baterie în handlerul ochelarilor; există și builder comun cu ctrl pentru înregistrare'],['62004','Stare în handlerul ochelarilor; aceeași constantă are alte sensuri în codul comun'],['62005','HELLO în handlerul ochelarilor; builder separat SetSystemInfoParam: userId, activeRecord, audType, unbind'],['62201','Pornire: translationScene, multiModeSwitch, compressionRatio'],['62202','Oprire: translationScene opțional'],['62205 / 62206','originalSoundSwitch / translateSoundSwitch'],['62208','compressionRatio'],['62212','selfOriginalSoundSwitch, peerOriginalSoundSwitch'],['62305','Text către ochelari: isTemp, text, is_trans, type, seg_start, txt_serial, seg_serial, flowNo, srcLan, destLan, index, total'],['62132','pairedUserId'],['62135','Text AI: text, mode, sessionId, index, isFinal'],['62142 / 62143','Setare/citire luminozitate; brightness la setare'],['62144 / 62145','Setare/citire înălțime; height la setare'],['62146 / 62147','Setare/citire afișare traducere; viewId, fontSize, showMode'],['62125 / 62127','Parametri/control teleprompter prin obiecte toMap()'],['70401','Control Wi-Fi: ctrl, ssid, pwd, wifiType, wifiBand, wifiChannel, encryption'],['70400','Listă fișiere: pageNum, pageSize, fileType, wifiFileList opțional'],['70405','Ștergere în builderul BLE: deleteFileName, fileType'],['62401…62407','Familie OTA algoritm; tipul și suportul diferă între dispozitive']])+`<p class="note">Coliziunile de mai sus sunt reale în APK. Nu folosi lista veche IBluetoothProtocol drept dicționar unic pentru GLASSES. Alege profilul, handlerul și capabilitățile dispozitivului. Unele funcții sunt pentru căști sau alte produse.</p><p><a href="CATALOG.html">Catalogul complet</a> conține toți cei 103 constructori BLE și 9 Wi-Fi identificați în zb0/zka, inclusiv parametrii dinamici, toMap() și expresiile nesoluționate. Sunt constructori, nu 112 coduri opt distincte. Schemele arată câmpurile extrase, nu o schemă JSON Schema cu toate constrângerile inferate.</p><p>Coada verifică operația așteptată în unele căi; familia OTA are și comparare explicită opt + optNum. Nu presupune că toate răspunsurile sunt corelate strict după optNum. Modelele de stare includ notificări pentru baterie, purtare, gesturi/butoane, text, teleprompter, media și erori. ${ref('com/iflytek/easytrans/headset/bluetooth/device/CoreBluetoothDevice.java','Dispatcherul complet al răspunsurilor/notificărilor')}</p>`;
b+=`<h2 id="audio">5. Payload audio</h2><p>Parserul efectiv din Bluetooth este m07 (PayLoadEarAudio), apelat pentru moduleID 2 sau 4. Varianta este selectată din versiunea cadrului primit, nu presupusă din versiunea cadrului de comandă emis.</p>`+table(['Versiune primită','Layout payload, începând de la offsetul global 14'],[['1 și alte valori decât 2/3','moduleID:1 | msgID:1 | type:1 | chunk:4 big-endian | audio:N'],['2','moduleID:1 | msgID:1 | type:1 | cr:1 | chunk:4 big-endian | audio:N'],['3','moduleID:1 | msgID:1 | type:1 | compressionRate:1 | bizId:2 big-endian | chunk:4 big-endian | audio:N']])+`<p>Endianness diferă intenționat: antetul este little-endian, în timp ce m07 citește chunk cu ml0.b în big-endian. CoreBluetoothDevice extrage și octetul superior al chunk pentru contabilizarea pierderilor; nu interpreta automat acest câmp ca un simplu număr monoton de pachet.</p>`+table(['type','Sens din aplicație'],[['0','default'],['1 / 2','left ear / right ear'],['3 / 4','near end / far end'],['5 / 6','glass self / glass other']])+`<p>Acestea sunt etichete logice, nu dovada a șapte microfoane fizice. Decoderul Opus analizat lucrează la 16 kHz, cu căi mono și stereo și ieșire PCM signed 16-bit little-endian. Câmpul cr selectează și blocuri de 40/80/160 octeți în anumite căi. Maparea completă codec/rată/mod necesită verificarea versiunii și captură audio.</p><p>Există separat PayLoadAudio în pachetul Wi-Fi: moduleID, msgID, chunk BE pe 4 octeți și date cu lungime multiplu de 128. Acest parser are alt layout decât m07. În sensul telefon→ochelari, zb0.L1 folosește opCode=3, moduleID din profil (2), msgID=1 și un blob audio primit de la apelant; nu introduce automat headerul audio de recepție.</p><p>${ref(ob+'m07.java','m07')} · ${ref(ob+'ml0.java','Conversii de octeți')} · ${ref(wifi+'wifi/protocol/PayLoadAudio.java','Parserul audio din modulul Wi-Fi')}.</p>`;
b+=`<h2 id="wifi">6. Wi-Fi Direct, TCP, fișiere și OTA</h2><p>Aplicația creează/conectează rețeaua P2P și trimite configurarea prin BLE. Builderul h1 include encryption="wpa2". Fluxul startGlassWifi folosește wifiType=0, wifiBand="5" și canal 0; acestea sunt valori ale acestei căi, nu garanții pentru orice firmware.</p>`+code(JSON.stringify(examples.wifiStart,null,2))+`<p>connectSocket$lambda$6 conectează un socket TCP la IP-ul primit și portul <b>6688</b>, cu timeout de conectare de 5 s. Portul 8888 apare într-o cale de server/test; nu este dedus ca port principal al ochelarilor. Sunt folosite Socket/Network socket factory; nu apare un strat TLS în această cale locală. Protecția rețelei WPA2 este un nivel separat.</p><p>${ref(wifi+'WiFiDirectTestManager.java','Conectarea și transferul')} · ${ref(ob+'jja.java','Constanta port 6688')} · ${ref(ob+'zka.java','WifiFrameBuilder')}.</p><p>TCP transportă aceleași cadre AA FF 55 00, nu un document JSON delimitat prin newline. Pentru fișiere, payload-ul modulului 3 are următoarea structură:</p>`+table(['Offset în payload','Octeți','Conținut'],[['0','1','moduleID=3'],['1','1','msgID; 1 în builderul de upload/OTA analizat, 2 într-o altă cale BLE'],['2','4','totalChunkNum, little-endian'],['6','4','curChunkNum, little-endian'],['10','1','remainChunkNum'],['11','N','Date binare ale blocului']])+`<p>Cadru total: N+26; length=N+12. Structura nu este același lucru cu forma specială AlgoOtaChunk: moduleID=3, msgID=1, type:1, curChunkNum:4 LE, isLastChunk:1, date; în acea variantă cadrul are N+23. Nu se amestecă cele două formate.</p>`+table(['opt Wi-Fi','Parametri verificați'],[['70406','Listă: fileType, pageSize, pageNum'],['70402','Transfer: ctrl, model=2, upOrDown, fileName, offset; upload adaugă md5/fileSize/breakPoint'],['70403','ACK/selectarea blocurilor: bitMap, startIdx'],['70404','Ștergere: dirName, state=1 în builderul Wi-Fi'],['70401','Oprire Wi-Fi: ctrl=0'],['79901','Handshake OTA: status, handshake=1'],['62016','Builder HELLO existent; sendSayHello() este gol în managerul Wi-Fi inspectat']])+`<p>ctrl: 0 pauză, 1 start, 2 continuare, 3 stop; upOrDown: 1 upload, 2 download. Builderul download cere fileNoCrc=1; managerul decide apoi skipFileDataCrc pe baza răspunsului dispozitivului. Excepția privește moduleID=3, nu toate comenzile. MD5-ul fișierului și CRC-ul cadrului sunt verificări distincte; nu sunt semnături de autentificare.</p>`+code(JSON.stringify(examples.wifiDownload,null,2))+`<p>bitMap/startIdx, offset și uploadBreakPoint permit urmărirea/reluarea transferului în implementare. Semantica exactă a fiecărui bit și comportamentul după reconectare trebuie corelate cu SyncRequestWifi și firmware-ul. ${ref(wifi+'SyncRequestWifi.java','SyncRequestWifi')} · ${ref(wifi+'wifi/protocol/PayLoadFileSync.java','Payload fișier')}.</p>`;
b+=`<h2 id="cloud">7. API cloud STT / Translate / TTS</h2><p>TranslateManager selectează ClientHost din ReqbaseParams folosind hostId. ClientHost conține host, port, certificate. path poate veni de la Flutter, deci nu există o adresă unică fixă demonstrată pentru toate sesiunile. Managerul BLC construiește transport TLS. <b>Nu sunt endpointuri REST obișnuite doar fiindcă au forma /v3/...</b></p>`+table(['Scenariu din selectorul local','Cale gRPC implicită observată'],[['VOICE','/v3/audiotrans/trans'],['TEXT','/v3/texttrans/trans'],['OCR','/v3/imagetrans/trans'],['OCR_IMG2IMG','/v3/imagetrans/ldtrans'],['SCRAWL','/v3/imagetrans/applytrans'],['TTS','/v3/tts/tts'],['TALK_V3','/v3/isttrans/trans']])+`<p>Aceste valori provin din selectorul getMethodName și pot fi suprascrise prin configurarea sesiunii. AIHelper, AISummary, AIInterpretation și AIChatPartner au fluxuri separate; schema de mai jos descrie marshallerul comun STT/traducere/TTS, nu orice serviciu AI inclus.</p><p>${ref('translate_sdk/TranslateManager.java','Selector și manager')} · ${ref('translate_sdk/ClientHost.java','ClientHost')} · ${ref('com/iflytek/fanyi/blc/manager/TranslateManager.java','Transport TLS')} · ${ref('com/iflytek/fanyi/blc/service/impl/TranslateServiceImpl.java','Serviciile gRPC')}.</p><h3>Formatul mesajelor cloud</h3><p>gRPC standard adaugă un octet pentru compresie și o lungime big-endian pe 4 octeți înaintea mesajului. Cadrul HTTP/2 este un nivel exterior și poate fragmenta mesajul. <a href="https://github.com/grpc/grpc/blob/master/doc/PROTOCOL-HTTP2.md">Specificația gRPC</a>.</p>`+code('HTTP/2 DATA\n└─ gRPC: compressedFlag:uint8 | messageLength:uint32BE | MESSAGE\n\nMESSAGE pentru clasele care NU extind Buffer:\n  JSON UTF-8\n\nMESSAGE pentru clasele care extind Buffer:\n  jsonLength:uint32BE | JSON UTF-8 | date binare rămase\n\nNu se adaugă CRC-ul BLE la un mesaj gRPC.')+`<p>Marshallerul k36 verifică moștenirea Buffer. mData este transient și se scrie separat de JSON; nu este codificat automat Base64. Prefixul JSON folosește mi0.writeInt, verificat big-endian. Clasele audio și unele răspunsuri moștenesc Buffer; cererea TxtTransRequest nu îl moștenește.</p><p>${ref(ob+'k36.java','MixMarshaller')} · ${ref(ob+'mi0.java','readInt/writeInt')} · ${ref(bean+'Buffer.java','Buffer')}.</p><h3>Schema audio uzuală</h3>`+code(JSON.stringify(examples.cloudAudio,null,2))+`<p>Exemplul este ilustrativ; framesize=640 corespunde matematic unei bucăți PCM mono de 20 ms la 16 kHz/16 biți, dar nu fixează durata obligatorie a protocolului. Valorile limbilor, credențialelor și parametrilor trebuie furnizate de configurația reală.</p>`+table(['Câmp','Rol din modele'],[['type','data; close este folosit de close()'],['s','ID sesiune'],['l','Flag de sfârșit mIsEnd, nu litera i'],['cid','ID conversație/corelare opțional'],['c.base','Identitate client/dispozitiv/aplicație'],['c.param','Token, limbi, VAD, voci, codecuri și parametri ai scenariului'],['reqcodec / rescodec','format, rate, bit, channels, framesize'],['source / target','source este un array de limbi; target este string'],['autotts','Atenție la tip: string în Param audio, boolean în TxtInitRequest.Param'],['pgsflag / retdirectpgs','Control rezultate progresive'],['vadtime','Parametru de delimitare vocală; unitatea trebuie verificată în contractul serverului'],['roleseparate / transdirection','Separare vorbitori / direcție, în căile care le folosesc'],['llmtransparam','Hartă pentru traducere cu LLM; nu nume sau versiune de model garantată'],['livereqparam / rightparam','Parametri ai fluxului live și drepturilor/scenariului']])+`<p>e95 comprimă semantic antetul unor cadre LongAudioTransRequest ulterioare: poate păstra doar type=data și subsetul c.param. c.base, s sau l nu apar obligatoriu în fiecare mesaj. Lista DTO-urilor nu este suficientă pentru a deduce mesajul final fără verificarea serializerului. ${ref(ob+'e95.java','Serializerul special pentru audio lung')}.</p><h3>Răspunsuri</h3><p>ResponseType definește iat, its, tts, ocr și ctr. AudioTransResponse/LongAudioTransResponse includ c (cod), d (descriere), t (tip), r (rezultat), s (sesiune), l (sfârșit), pgs, textstart/textend/textserial, iatresulttime și alte câmpuri. Dacă răspunsul extinde Buffer, datele audio sunt după JSON în payloadul binar. BlcUtils consideră codul string "000000" succes; acesta diferă de errCode=0 din BLE și de grpc-status=0 din transport.</p><p>${ref(bean+'ResponseType.java','Tipuri rezultate')} · ${ref(bean+'AudioTransResponse.java','Răspuns audio')} · ${ref('com/iflytek/fanyi/blc/manager/BlcUtils.java','Cod succes')} · <a href="schemas.json">Toate câmpurile extrase</a>.</p>`;
b+=`<h2 id="chei">8. Chei, identificatori și autentificare</h2>`+table(['Element','Ce reprezintă / ce este confirmat'],[['UUID GATT','Identificator public de serviciu/caracteristică; nu parolă'],['opt / optNum / biz_num / sequenceId','Operație și corelare; nu autentificare'],['CRC-8 / MD5 / crc32','Integritatea cadrului/fișierului după calea folosită; nu dovadă de identitate'],['pairedUserId / userId / unbind','Asocierea cu utilizatorul; nu demonstrează singure un mecanism criptografic'],['ssid / pwd / encryption','Configurarea rețelei Wi-Fi; builderul specifică WPA2'],['hostId','Cheie de selecție în harta de servere, nu API key'],['certificate','Material de certificat pentru transportul TLS; nu o cheie privată TLS'],['appid / accesskey / bizid / caller','Identitatea/configurația clientului în c.base; rolul exact al accesskey în verificarea serverului nu este expus complet'],['uid / deviceid / androidid / modelid / pver / version','Metadate ale utilizatorului, dispozitivului și protocolului'],['token','Transmis din Flutter în BaseClientParams și în parametrii cererii; valoarea și durata de viață sunt externe acestei analize'],['sauthid / sauthtime','Câmpuri ale sesiunii de autentificare din Param'],['X-sign','Antet ASCII setat de createAuthTransStream; valoarea este primită de la apelant'],['idexpire / timestamp','Câmpuri din cererea de autentificare; semnificația și unitățile exacte cer contractul serverului']])+`<p>AuthTransRequest conține c.base și c.param cu idexpire, sauthid, timestamp. AuthTransResponse conține retcode, retdesc, sauthid, timestamp. Faptul că aceste clase sunt incluse nu demonstrează folosirea lor în fiecare sesiune. Nu a fost identificat aici traseul complet care produce X-sign; nu îl etichetez automat HMAC-SHA256 sau MD5.</p><p>Nu există în această documentație o cheie universală funcțională care să înlocuiască loginul sau drepturile contului. Nu am derivat tokenuri, chei de sesiune ori chei private. Builderul BLE observat scrie JSON fără un pas de criptare aplicativă în acel constructor; acest lucru nu dovedește absența criptării la nivel radio sau a altor verificări în firmware.</p><p>${ref(bean+'Base.java','Câmpurile identității')} · ${ref(bean+'Param.java','Parametrii autentificați')} · ${ref(bean+'AuthTransRequest.java','Cerere auth')} · ${ref(bean+'AuthTransResponse.java','Răspuns auth')} · ${ref('com/iflytek/fanyi/blc/manager/AuthTransSession.java','Sesiune auth')}.</p>`;
b+=`<h2 id="flutter">9. API-ul intern Flutter și API-uri auxiliare</h2><p>bluetooth_manager_plugin, recorde_translate_plugin, wifi_manager_plugin și component_online_translate_flutter sunt canale în procesul aplicației. Metode precum scan, connectDevice, startRecord, startGlassWifi, textTranslate și startTts ajung la pluginurile native. Nu sunt adrese HTTP și nu sunt expuse automat altor aplicații instalate.</p><p><a href="../inventar/flutter-channel-contracts.json">Inventar de canale și șiruri candidate Flutter</a> · <a href="../documentatie/flutter-contracts.txt">Variantă text</a>. Lista automată include și candidați proveniți din evenimente/enumuri, nu doar metode invocabile.</p><p>În Dart AOT există și referințe /business/v1/teleprompter/create, delete, detail, list, setOnGlass, update. Sunt indicii de rute auxiliare; nu am reconstruit din aceste șiruri metoda HTTP, corpul și autentificarea. ${ref('com/example/recorde_translate_plugin/glass/wifip2p/WifiManagerPlugin.java','Plugin Wi-Fi')} · <a href="../nativ/dart-aot-identifiers.txt">Identificatori AOT</a>.</p>`;
b+=`<h2 id="limite">10. Verificări, limite și integrare</h2><p>Verificate local: fixture-ul baterie din SDK, CRC-8 pe cadru, existența surselor și legăturilor. Nu au fost efectuate accesări cloud autentificate, comenzi BLE, transferuri sau OTA. Pentru un client interoperabil rămân de verificat pe modelul/firmware-ul real: capabilitățile GATT, MTU, asocierea/activarea, succesiunea exactă HELLO/configurare, versiunea payloadului audio, răspunsurile reale și credențialele obținute legitim prin cont.</p><p>Acoperirea este a traseelor ochelari–aplicație și traducere analizate. SDK-urile de plăți, telemetrie și dependențele Android incluse în APK nu sunt specificate integral aici. Sursele Dart AOT, codul firmware și backendul nu sunt complet vizibile; nu afirm că documentul este întregul protocol proprietar al producătorului.</p><p>Proveniență APK SHA-256: <code>73170cdc5c3331cd6055607015c04ed8e0a314f4c0bd2fd4651e2b732d1b3da2</code>. Extracțiile suplimentare sunt regenerabile cu tools/protocol-inventory.cjs și tools/protocol-report.cjs.</p>`;
